def new_board():
    b = [['.'] * 8 for _ in range(8)]
    for r in list(range(3)) + list(range(5, 8)):
        for c in range(8):
            if (r + c) % 2:
                b[r][c] = 'r' if r < 3 else 'b'

def promote(p, tr):
    if p == 'r' and tr == 7:
        return 'R', True
    if p == 'b' and tr == 0:
        return 'B', True
    return p, False

def dirs_of(p):
    if p.isupper():
        return ((1, -1), (1, 1), (-1, -1), (-1, 1))
    return ((1, -1), (1, 1)) if p == 'r' else ((-1, -1), (-1, 1))
